WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT s.id, s.customer_id, s.device, s.browser, s.country, s.is_new_session, (SELECT MAX(o2.discount) FROM orders o2 WHERE o2.customer_id = s.customer_id) AS max_order_discount FROM islands s
